"""Write apps/mobile/src/brand/hum.ts from the geometry hum_kit.py exports.

    python hum_kit.py /tmp/hum && python write_ts.py /tmp/hum/hum-geometry.json ../../apps/mobile/src/brand/hum.ts
"""
import json, sys

geometry, target = sys.argv[1], sys.argv[2]
g = json.load(open(geometry))
ring, core, wm = g["ring"], g["core"], g["wordmark"]
src = f'''/**
 * Hum, the Luvani mark: the tutor's orb, humming. A solid core sits inside a
 * ring that ripples like a voice, seven lobes with one pointing straight up.
 *
 * Generated by brand/source/hum_kit.py from the same geometry as every master
 * in apps/mobile/assets/brand and brand/, so the launch screen draws exactly
 * the mark on the icon and the splash. Do not edit the paths by hand: change
 * the generator and run it again. src/launch/launchScreen.test.ts holds the
 * ring here to the ring in assets/brand/luvani-mark.svg.
 */

/** The square canvas every Hum master is drawn on. The mark spans 224 of it. */
export const HUM_VIEWBOX = {g["viewBox"]};

/** The rippling ring, as one filled outline. */
export const HUM_RING_PATH =
  '{ring}';

/** The solid core. */
export const HUM_CORE = {{ cx: {core["cx"]}, cy: {core["cy"]}, r: {core["r"]} }} as const;

/** The rounded lowercase wordmark, drawn on its own box. */
export const HUM_WORDMARK = {{
  width: {wm["width"]},
  height: {wm["height"]},
  d: '{wm["d"]}',
}} as const;
'''
open(target, "w").write(src)
print("wrote", target)
